head.script:
let eCount_1 = 0;
let eCount_2 = 0;
let eCount_3 = 0;


// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > E > onkeydown]<br/>SearchBox 컴포넌트에서 키보드 키를 눌렀을 때 발생합니다.",
    "validation" : [
        "SearchBox 컴포넌트에서 키보드 키를 눌렀을 때 onkeydown 이벤트가 발생합니다.",
        "이벤트 객체 e (KeyboardEvent) 가 핸들러에 전달되어야 합니다.",        
        "입력값 변경 시 'onkeydown -> onkeypress -> onkeyup' 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 카운터 초기화
    eCount_1 = 0;
    eCount_2 = 0;
    eCount_3 = 0;

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // onkeydown -> onkeypress -> onkeyup 발생 순서 검증을 위해 3개 이벤트 모두 등록
    let eList = $c.gcm.createEList(["onkeydown", "onkeypress", "onkeyup"]);

    // comp 생성 함수 호출 (searchbox 는 비동기 plugin → await 필수)
    await $c.gcm.createBasicSearchBox('', eList);
}



scwin.target1_onkeydown = function (e) {
    // 이벤트 3번만 발생하게 처리
    if (eCount_1 < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeydown 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);

        if (eCount_1 == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }
    }
    eCount_1 += 1;
}



scwin.target1_onkeypress = function (e) {
    // 이벤트 3번만 발생하게 처리
    if (eCount_2 < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeypress 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);

        if (eCount_2 == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }
    }
    eCount_2 += 1;
}



scwin.target1_onkeyup = function (e) {
    // 이벤트 3번만 발생하게 처리
    if (eCount_3 < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeyup 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);

        if (eCount_3 == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }
    }
    eCount_3 += 1;
}
